import emailjs from "emailjs-com";
import { addDoc, collection, serverTimestamp } from "firebase/firestore";
import type { BookingRequest } from "../interfaces";
import { getEmailJsConfig } from "./emailJsConfig";

const DEFAULT_BOOKING_COLLECTION = "booking_requests";

async function getFirestoreInstance() {
  const { db } = await import("../../firebaseConfig");
  return db;
}

async function persistBookingRequest(request: BookingRequest) {
  try {
    const db = await getFirestoreInstance();

    await addDoc(
      collection(
        db,
        process.env.GATSBY_FIREBASE_BOOKING_COLLECTION || DEFAULT_BOOKING_COLLECTION,
      ),
      {
        ...request,
        createdAt: serverTimestamp(),
        createdAtIso: new Date().toISOString(),
      },
    );
  } catch (error) {
    console.error("Failed to persist booking request in Firebase.", error);
  }
}

function buildEmailPayload(request: BookingRequest) {
  return {
    name: request.name,
    phone: request.phone,
    email: request.email,
    destination: request.destination,
    adults: String(request.adults),
    children: String(request.children),
    comments: request.comments || "-",
    travel_start_date: request.travelStartDate,
    travel_end_date: request.travelEndDate,
    travel_date_range: `${request.travelStartDate} - ${request.travelEndDate}`,
  };
}

export async function submitBookingRequest(
  request: BookingRequest,
  recaptchaToken?: string,
) {
  const emailJsConfig = getEmailJsConfig("GATSBY_EMAILJS_TEMPLATE_ID");

  if (!emailJsConfig) {
    throw new Error("BOOKING_EMAIL_NOT_CONFIGURED");
  }

  await emailjs.send(
    emailJsConfig.serviceId,
    emailJsConfig.templateId,
    {
      ...buildEmailPayload(request),
      recaptcha_token: recaptchaToken || "",
    },
    emailJsConfig.publicKey,
  );

  await persistBookingRequest(request);
}
