import * as React from "react";
import { graphql, HeadFC, PageProps } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/layout";
import BookingForm from "../components/bookingForm";
import SEO from "../components/seo";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import images from "../images";

const userData = data;

const companyData: Company = {
  whatsapp: "",
  companyName: data.name,
  address: data.address,
  city: data.city,
  province: data.province,
  country: "Canada",
  phone: data.phone,
  email: data.email,
  instagram: data.instagram,
  facebook: data.facebook,
  menu: data.menu,
  linkedin: "",
  postalCode: data.postalCode,
  url: data.url,
};

const pageDescription = [data.address, data.city, data.province]
  .filter(Boolean)
  .join(", ");

const BookPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  const nextSteps = [
    t("bookPage.nextSteps.one"),
    t("bookPage.nextSteps.two"),
    t("bookPage.nextSteps.three"),
  ];

  return (
    <Layout data={userData}>
      <section className={styles.page}>
        <article className={styles.hero}>
          <img
            className={styles.heroImage}
            src={images.venice.src}
            alt={images.venice.alt}
          />
          <div className={styles.heroOverlay}>
            <div className={styles.heroCopy}>
              <p className={styles.eyebrow}>{t("menu.book")}</p>
              <h1 className={styles.heroTitle}>{t("bookPage.hero.title")}</h1>
              <p className={styles.heroSubtitle}>{t("bookPage.hero.subtitle")}</p>
            </div>
          </div>
        </article>

        <article className={styles.contentSection}>
          <section className={styles.copyColumn}>
            <div className={styles.copyCard}>
              <p className={styles.sectionEyebrow}>{t("bookPage.intro.eyebrow")}</p>
              <h2 className={styles.sectionTitle}>{t("bookPage.intro.title")}</h2>
              <p className={styles.sectionBody}>{t("bookPage.intro.body")}</p>
            </div>

            <div className={styles.stepsCard}>
              <h2 className={styles.sectionTitle}>{t("bookPage.nextSteps.title")}</h2>
              <ul className={styles.stepsList}>
                {nextSteps.map((step) => (
                  <li key={step} className={styles.stepItem}>
                    {step}
                  </li>
                ))}
              </ul>
            </div>
          </section>

          <section className={styles.formColumn}>
            <BookingForm />
          </section>
        </article>
      </section>
    </Layout>
  );
};

export default BookPage;

export const Head: HeadFC = ({ pageContext }) => {
  const i18n = (pageContext as
    | {
        i18n?: {
          language?: string;
          languages?: string[];
          defaultLanguage?: string;
          originalPath?: string;
        };
      }
    | undefined)?.i18n;

  return (
    <SEO
      data={companyData}
      title={userData.name}
      description={pageDescription || userData.name}
      schemaName={userData.name}
      pathname="/book"
      language={i18n?.language}
      languages={i18n?.languages}
      defaultLanguage={i18n?.defaultLanguage}
      originalPath={i18n?.originalPath}
    />
  );
};

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  page: "flex flex-col items-center",
  hero: "relative w-full",
  heroImage: "h-[44vh] min-h-[360px] w-full object-cover",
  heroOverlay:
    "absolute inset-0 bg-gradient-to-r from-secondary/90 via-secondary/62 to-secondary/18",
  heroCopy:
    "mx-auto flex h-full w-full max-w-[1400px] flex-col justify-center gap-3 px-4 py-12 text-contrast sm:px-8",
  eyebrow: "menu_desk uppercase tracking-[0.24em] text-contrast/80",
  heroTitle: "h1_desk max-w-4xl text-contrast",
  heroSubtitle: "body_desk max-w-2xl text-contrast/90",
  contentSection:
    "mx-auto grid w-full max-w-[1400px] gap-6 px-4 py-10 sm:px-8 sm:py-14 lg:grid-cols-[0.9fr_1.1fr]",
  copyColumn: "flex flex-col gap-6",
  formColumn: "min-w-0",
  copyCard:
    "rounded-[28px] border border-secondary/15 bg-secondary/8 p-6 shadow-[0_24px_60px_rgba(0,0,0,0.06)]",
  stepsCard:
    "rounded-[28px] border border-main/10 bg-terciary/10 p-6 shadow-[0_24px_60px_rgba(0,0,0,0.05)]",
  sectionEyebrow: "menu_desk uppercase tracking-[0.18em] text-secondary",
  sectionTitle: "h2_desk mt-3 text-secondary",
  sectionBody: "body_desk mt-4 max-w-2xl text-main/80",
  stepsList: "mt-5 flex flex-col gap-3",
  stepItem:
    "body_desk rounded-full border border-main/10 bg-contrast/80 px-4 py-3 text-main/85 backdrop-blur-sm",
};
