import * as React from "react";
import {
  Alert,
  Box,
  Button,
  Paper,
  Stack,
  TextField,
  Typography,
} from "@mui/material";
import { useTranslation } from "gatsby-plugin-react-i18next";
import type { BookingRequest } from "../interfaces";
import { submitBookingRequest } from "../services/bookingRequest";
import { executeRecaptchaV3 } from "../services/recaptchaV3";

type BookingFormValues = {
  [Key in keyof BookingRequest]: string;
};

type BookingFormErrors = Partial<Record<keyof BookingFormValues, string>>;
type BookingFormTouched = Partial<Record<keyof BookingFormValues, boolean>>;

const initialFormValues: BookingFormValues = {
  name: "",
  phone: "",
  email: "",
  travelStartDate: "",
  travelEndDate: "",
  destination: "",
  children: "0",
  adults: "2",
  comments: "",
};

const textFieldSx = {
  "& .MuiInputLabel-root": {
    color: "rgba(0, 0, 0, 0.7)",
  },
  "& .MuiInputLabel-root.Mui-focused": {
    color: "#4ecdc4",
  },
  "& .MuiOutlinedInput-root": {
    borderRadius: "16px",
    backgroundColor: "rgba(247, 248, 238, 0.72)",
  },
  "& .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline": {
    borderColor: "#4ecdc4",
  },
};

function toBookingRequest(formValues: BookingFormValues): BookingRequest {
  return {
    ...formValues,
    adults: Number(formValues.adults),
    children: Number(formValues.children),
  };
}

export default function BookingForm() {
  const { t } = useTranslation();
  const [formValues, setFormValues] = React.useState(initialFormValues);
  const [formErrors, setFormErrors] = React.useState<BookingFormErrors>({});
  const [touchedFields, setTouchedFields] = React.useState<BookingFormTouched>({});
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [status, setStatus] = React.useState<{
    severity: "success" | "error";
    message: string;
  } | null>(null);

  function translate(key: string) {
    return String(t(key));
  }

  function isValidEmail(email: string) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  function validate(values: BookingFormValues) {
    const nextErrors: BookingFormErrors = {};
    const adults = Number(values.adults);
    const children = Number(values.children);

    if (!values.name.trim()) {
      nextErrors.name = translate("bookForm.validation.required");
    }

    if (!values.phone.trim()) {
      nextErrors.phone = translate("bookForm.validation.required");
    }

    if (!values.email.trim()) {
      nextErrors.email = translate("bookForm.validation.required");
    } else if (!isValidEmail(values.email.trim())) {
      nextErrors.email = translate("bookForm.validation.invalidEmail");
    }

    if (!values.travelStartDate) {
      nextErrors.travelStartDate = translate("bookForm.validation.required");
    }

    if (!values.travelEndDate) {
      nextErrors.travelEndDate = translate("bookForm.validation.required");
    }

    if (
      values.travelStartDate &&
      values.travelEndDate &&
      values.travelEndDate < values.travelStartDate
    ) {
      nextErrors.travelEndDate = translate("bookForm.validation.invalidDateRange");
    }

    if (!values.destination.trim()) {
      nextErrors.destination = translate("bookForm.validation.required");
    }

    if (!Number.isInteger(adults) || adults < 1) {
      nextErrors.adults = translate("bookForm.validation.minAdults");
    }

    if (!Number.isInteger(children) || children < 0) {
      nextErrors.children = translate("bookForm.validation.minChildren");
    }

    return nextErrors;
  }

  function getFieldError(
    fieldName: keyof BookingFormValues,
    values: BookingFormValues,
  ) {
    return validate(values)[fieldName];
  }

  function handleFieldChange(
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) {
    const { name, value } = event.target;

    setFormValues((currentValues) => ({
      ...currentValues,
      [name]: value,
    }));

    setFormErrors((currentErrors) => {
      const fieldName = name as keyof BookingFormValues;

      if (!touchedFields[fieldName] && !currentErrors[fieldName]) {
        return currentErrors;
      }

      const nextErrors = { ...currentErrors };
      const nextFieldError = getFieldError(fieldName, {
        ...formValues,
        [fieldName]: value,
      });

      if (nextFieldError) {
        nextErrors[fieldName] = nextFieldError;
      } else {
        delete nextErrors[fieldName];
      }

      return nextErrors;
    });

    if (status) {
      setStatus(null);
    }
  }

  function handleFieldBlur(
    event: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) {
    const { name } = event.target;
    const fieldName = name as keyof BookingFormValues;

    setTouchedFields((currentTouched) => ({
      ...currentTouched,
      [fieldName]: true,
    }));

    setFormErrors((currentErrors) => {
      const nextErrors = { ...currentErrors };
      const nextFieldError = getFieldError(fieldName, formValues);

      if (nextFieldError) {
        nextErrors[fieldName] = nextFieldError;
      } else {
        delete nextErrors[fieldName];
      }

      return nextErrors;
    });
  }

  function handleResetBooking() {
    setFormValues(initialFormValues);
    setFormErrors({});
    setTouchedFields({});
    setStatus(null);
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    const nextErrors = validate(formValues);

    if (Object.keys(nextErrors).length > 0) {
      setTouchedFields({
        name: true,
        phone: true,
        email: true,
        travelStartDate: true,
        travelEndDate: true,
        destination: true,
        adults: true,
        children: true,
        comments: true,
      });
      setFormErrors(nextErrors);
      setStatus({
        severity: "error",
        message: translate("bookForm.status.validationError"),
      });
      return;
    }

    setIsSubmitting(true);
    setStatus(null);

    try {
      const recaptchaToken = await executeRecaptchaV3("booking_submit");

      await submitBookingRequest(toBookingRequest(formValues), recaptchaToken);
      setFormValues(initialFormValues);
      setFormErrors({});
      setTouchedFields({});
      setStatus({
        severity: "success",
        message: translate("bookForm.status.success"),
      });
    } catch (error) {
      const isConfigError =
        error instanceof Error &&
        (error.message === "BOOKING_EMAIL_NOT_CONFIGURED" ||
          error.message === "RECAPTCHA_NOT_CONFIGURED");
      const isRecaptchaError =
        error instanceof Error &&
        (error.message === "RECAPTCHA_LOAD_FAILED" ||
          error.message === "RECAPTCHA_UNAVAILABLE" ||
          error.message === "RECAPTCHA_EXECUTION_FAILED");

      setStatus({
        severity: "error",
        message: isConfigError
          ? translate("bookForm.status.serviceUnavailable")
          : isRecaptchaError
            ? translate("bookForm.status.recaptchaError")
            : translate("bookForm.status.error"),
      });
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <Paper
      elevation={0}
      sx={{
        borderRadius: "28px",
        border: "1px solid rgba(78, 205, 196, 0.18)",
        background:
          "linear-gradient(180deg, rgba(247, 248, 238, 0.94) 0%, rgba(247, 248, 238, 0.88) 100%)",
        p: { xs: 3, md: 4 },
        boxShadow: "0 24px 60px rgba(0, 0, 0, 0.08)",
      }}
    >
      {status?.severity === "success" ? (
        <Stack spacing={3}>
          <Box>
            <Typography
              variant="h5"
              sx={{
                fontFamily: '"Libre Baskerville", Georgia, serif',
                color: "#ff6b6b",
                fontWeight: 700,
              }}
            >
              {t("bookForm.successView.title")}
            </Typography>
            <Typography sx={{ mt: 1, color: "rgba(0, 0, 0, 0.72)" }}>
              {t("bookForm.successView.body")}
            </Typography>
          </Box>

          <Alert severity="success">{status.message}</Alert>

          <Stack
            direction={{ xs: "column", sm: "row" }}
            spacing={2}
          >
            <Button
              type="button"
              variant="contained"
              onClick={handleResetBooking}
              sx={{
                minHeight: 56,
                borderRadius: "999px",
                bgcolor: "#4ecdc4",
                color: "#0d3b37",
                fontWeight: 700,
                textTransform: "none",
                fontSize: "1rem",
                "&:hover": {
                  bgcolor: "#39b7af",
                },
              }}
            >
              {t("bookForm.successView.backToBooking")}
            </Button>

            <Button
              type="button"
              variant="outlined"
              href="/"
              sx={{
                minHeight: 56,
                borderRadius: "999px",
                borderColor: "rgba(78, 205, 196, 0.5)",
                color: "#0d3b37",
                fontWeight: 700,
                textTransform: "none",
                fontSize: "1rem",
                "&:hover": {
                  borderColor: "#39b7af",
                  backgroundColor: "rgba(78, 205, 196, 0.08)",
                },
              }}
            >
              {t("bookForm.successView.goHome")}
            </Button>
          </Stack>
        </Stack>
      ) : (
      <Stack component="form" spacing={3} onSubmit={handleSubmit}>
        <Box>
          <Typography
            variant="h5"
            sx={{
              fontFamily: '"Libre Baskerville", Georgia, serif',
              color: "#ff6b6b",
              fontWeight: 700,
            }}
          >
            {t("bookForm.title")}
          </Typography>
          <Typography sx={{ mt: 1, color: "rgba(0, 0, 0, 0.72)" }}>
            {t("bookForm.subtitle")}
          </Typography>
        </Box>

        {status ? <Alert severity={status.severity}>{status.message}</Alert> : null}

        <TextField
          label={t("bookForm.fields.name")}
          name="name"
          value={formValues.name}
          onChange={handleFieldChange}
          onBlur={handleFieldBlur}
          error={Boolean(formErrors.name)}
          helperText={formErrors.name}
          fullWidth
          required
          sx={textFieldSx}
        />

        <TextField
          label={t("bookForm.fields.phone")}
          name="phone"
          type="tel"
          value={formValues.phone}
          onChange={handleFieldChange}
          onBlur={handleFieldBlur}
          error={Boolean(formErrors.phone)}
          helperText={formErrors.phone}
          fullWidth
          required
          sx={textFieldSx}
        />

        <TextField
          label={t("bookForm.fields.email")}
          name="email"
          type="email"
          value={formValues.email}
          onChange={handleFieldChange}
          onBlur={handleFieldBlur}
          error={Boolean(formErrors.email)}
          helperText={formErrors.email}
          fullWidth
          required
          sx={textFieldSx}
        />

        <Box
          sx={{
            display: "grid",
            gap: 2,
            gridTemplateColumns: { xs: "1fr", md: "repeat(2, minmax(0, 1fr))" },
          }}
        >
          <TextField
            label={t("bookForm.fields.travelStartDate")}
            name="travelStartDate"
            type="date"
            value={formValues.travelStartDate}
            onChange={handleFieldChange}
            onBlur={handleFieldBlur}
            error={Boolean(formErrors.travelStartDate)}
            helperText={formErrors.travelStartDate}
            fullWidth
            required
            sx={textFieldSx}
            slotProps={{
              inputLabel: {
                shrink: true,
              },
            }}
          />

          <TextField
            label={t("bookForm.fields.travelEndDate")}
            name="travelEndDate"
            type="date"
            value={formValues.travelEndDate}
            onChange={handleFieldChange}
            onBlur={handleFieldBlur}
            error={Boolean(formErrors.travelEndDate)}
            helperText={formErrors.travelEndDate}
            fullWidth
            required
            sx={textFieldSx}
            slotProps={{
              inputLabel: {
                shrink: true,
              },
              htmlInput: {
                min: formValues.travelStartDate || undefined,
              },
            }}
          />
        </Box>

        <TextField
          label={t("bookForm.fields.destination")}
          name="destination"
          value={formValues.destination}
          onChange={handleFieldChange}
          onBlur={handleFieldBlur}
          error={Boolean(formErrors.destination)}
          helperText={formErrors.destination}
          fullWidth
          required
          sx={textFieldSx}
        />

        <Box
          sx={{
            display: "grid",
            gap: 2,
            gridTemplateColumns: { xs: "1fr", md: "repeat(2, minmax(0, 1fr))" },
          }}
        >
          <TextField
            label={t("bookForm.fields.adults")}
            name="adults"
            type="number"
            value={formValues.adults}
            onChange={handleFieldChange}
            onBlur={handleFieldBlur}
            error={Boolean(formErrors.adults)}
            helperText={formErrors.adults}
            fullWidth
            required
            sx={textFieldSx}
            slotProps={{
              htmlInput: {
                min: 1,
                step: 1,
              },
            }}
          />

          <TextField
            label={t("bookForm.fields.children")}
            name="children"
            type="number"
            value={formValues.children}
            onChange={handleFieldChange}
            onBlur={handleFieldBlur}
            error={Boolean(formErrors.children)}
            helperText={formErrors.children}
            fullWidth
            required
            sx={textFieldSx}
            slotProps={{
              htmlInput: {
                min: 0,
                step: 1,
              },
            }}
          />
        </Box>

        <TextField
          label={t("bookForm.fields.comments")}
          name="comments"
          value={formValues.comments}
          onChange={handleFieldChange}
          onBlur={handleFieldBlur}
          fullWidth
          multiline
          minRows={5}
          sx={textFieldSx}
        />

        <Alert severity="info">{t("bookForm.recaptchaNotice")}</Alert>

        <Button
          type="submit"
          variant="contained"
          disabled={isSubmitting}
          sx={{
            minHeight: 56,
            borderRadius: "999px",
            bgcolor: "#4ecdc4",
            color: "#0d3b37",
            fontWeight: 700,
            textTransform: "none",
            fontSize: "1rem",
            "&:hover": {
              bgcolor: "#39b7af",
            },
            "&.Mui-disabled": {
              bgcolor: "rgba(78, 205, 196, 0.45)",
              color: "rgba(13, 59, 55, 0.72)",
            },
          }}
        >
          {isSubmitting
            ? t("bookForm.actions.submitting")
            : t("bookForm.actions.submit")}
        </Button>
      </Stack>
      )}
    </Paper>
  );
}
